(() => {
  // هر متغیری از params قابل استفاده است و کل API اندیکاتورها پارامتریک است.
  const fast = ema(c, params.emaFast);
  const slow = ema(c, params.emaSlow);
  const r = rsi(c, params.rsiPeriod);
  const a = atr(params.atrPeriod);
  const volOk = nz(sma(v, params.volPeriod)[i], 0) > 0
    ? v[i] >= params.volMult * sma(v, params.volPeriod)[i]
    : true;

  if (na(fast[i]) || na(slow[i]) || na(r[i]) || na(a[i])) {
    return { side: 'flat', strength: 0, reason: 'warmup' };
  }

  const up = crossOver(fast, slow)[i];
  const down = crossUnder(fast, slow)[i];
  const atrNow = a[i];

  if (up && r[i] < params.rsiMax && volOk) {
    return {
      side: 'long',
      strength: clamp((r[i] - params.rsiMin) / 40, 0.1, 1),
      reason: 'EMA' + params.emaFast + '/' + params.emaSlow + ' cross-up, RSI=' + round(r[i], 1),
      stopLoss: c[i] - atrNow * params.atrStopMult,
      takeProfit: c[i] + atrNow * params.atrTargetMult
    };
  }

  if (down && r[i] > params.rsiMin && volOk) {
    return {
      side: 'short',
      strength: clamp((params.rsiMax - r[i]) / 40, 0.1, 1),
      reason: 'EMA' + params.emaFast + '/' + params.emaSlow + ' cross-down, RSI=' + round(r[i], 1),
      stopLoss: c[i] + atrNow * params.atrStopMult,
      takeProfit: c[i] - atrNow * params.atrTargetMult
    };
  }

  return { side: 'flat', strength: 0, reason: 'no-edge' };
})()
